package ktanesolver.module.modded.regular.snooker;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;class SnookerSolverTest{private final SnookerSolver s=new SnookerSolver();@Test void findsLegalFourBreakClearanceAndStoresFinalAttemptReds(){ModuleEntity m=new ModuleEntity();List<Integer>targets=List.of(8,13,9,51);var out=((SolveSuccess<SnookerOutput>)s.solve(new RoundEntity(),new BombEntity(),m,new SnookerInput(8,targets))).output();assertThat(out.breaks()).hasSize(4);for(int i=0;i<4;i++)assertThat(out.breaks().get(i).stream().filter(x->!x.equals("cue")).mapToInt(SnookerSolverTest::points).sum()).isEqualTo(targets.get(i));assertThat(out.actions().getLast()).isEqualTo("cue");assertThat(m.getState()).containsEntry("snookerReds",8);}@Test void rejectsImpossibleOrMalformedFrames(){assertThat(s.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new SnookerInput(8,List.of(1,1,1,1)))).isInstanceOf(SolveFailure.class);assertThat(s.solve(new RoundEntity(),new BombEntity(),new ModuleEntity(),new SnookerInput(7,List.of(8,13,9,51)))).isInstanceOf(SolveFailure.class);}private static int points(String c){return List.of("","red","yellow","green","brown","blue","pink","black").indexOf(c);}}
